import { EVENT_KINDS, type EventKind } from '../calendar';
import { clockOfSessionMinute, sessionMinute } from '../time';
import type { ArithOp, Clause, CmpOp, EventKindName, EventOutcome, EventSpec, Expr, Field, Outcome, Span, Unit, Win } from './ast';
import { FIELDS } from './ast';
import { type Tok, isKeyword, lex, lineCol } from './lexer';
import { renderWinBase } from './render';

export type ParamUnit = 'none' | '%' | 'points' | 'minutes';
export interface ParamDecl {
  unit: ParamUnit;
  min: number | null;
  max: number | null;
  /** where the declaration came from: a preset declares; a document or the params map supplies plain numbers */
  source: 'preset' | 'document' | 'map';
}
export interface ParamEnv {
  values: Map<string, number>;
  decls: Map<string, ParamDecl>;
  used: Set<string>;
}

export interface RawError {
  code: string;
  offset: number;
  length: number;
  message: string;
}

export class SyntaxFail {
  constructor(readonly err: RawError) {}
}

export const BAR_SIZES = [1, 2, 3, 5, 10, 15, 20, 30, 60];
const PRICE_UNITS = new Set(['pt', 'pts', 'point', 'points', 'tick', 'ticks']);
const MINUTE_UNITS = new Set(['m', 'min', 'mins', 'minute', 'minutes']);
const HOUR_UNITS = new Set(['h', 'hr', 'hrs', 'hour', 'hours']);
const WEEKDAYS: Record<string, number> = {
  mon: 1, tue: 2, wed: 3, thu: 4, fri: 5,
  monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5,
};
const BAD_WEEKDAYS = new Set(['sat', 'sun', 'saturday', 'sunday']);
export const FUNCTIONS = ['window', 'bar', 'at', 'adr', 'atr', 'event', 'days_since', 'days_to', 'abs', 'min', 'max', 'mid', 'prior'];
export const VALUE_NAMES = [
  'rth', 'overnight', 'session', 'prior', 'gap', 'weekday', 'early_close',
  'fomc', 'cpi', 'nfp', 'opex', 'roll',
  'mon', 'tue', 'wed', 'thu', 'fri',
  ...FUNCTIONS,
];

export function levenshtein(a: string, b: string): number {
  const m = a.length, n = b.length;
  let prev = new Array<number>(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    const cur = new Array<number>(n + 1);
    cur[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[n];
}

/** ` Did you mean 'x'?` for the closest candidate within distance 2, else ''. */
export function suggest(text: string, candidates: readonly string[]): string {
  const t = text.toLowerCase();
  let best: string | null = null;
  let bestD = 3;
  for (const c of [...new Set(candidates)].sort()) {
    const d = levenshtein(t, c);
    if (d < bestD) {
      bestD = d;
      best = c;
    }
  }
  return best === null || best === t ? '' : ` Did you mean '${best}'?`;
}

function nameSuggestion(v: string): string {
  let m = /^prior([0-9]+)$/.exec(v);
  if (m) return ` Did you mean 'prior(${Number(m[1])})'?`;
  m = /^(?:orb|or_|opening)([0-9]+)$/.exec(v);
  if (m) return ` Did you mean 'or${Number(m[1])}'?`;
  return suggest(v, VALUE_NAMES);
}

type Arg =
  | { kind: 'time'; tok: Tok; name: string | null; span: Span }
  | { kind: 'duration'; minutes: number; name: string | null; span: Span }
  | { kind: 'ident'; tok: Tok; name: string | null; span: Span }
  | { kind: 'sum'; e: Expr; name: string | null; span: Span };

type Primary = { kind: 'expr'; e: Expr } | { kind: 'base'; win: Win; span: Span };

export class Parser {
  private i = 0;
  readonly checks: RawError[] = [];
  readonly toks: Tok[];
  /** canonical-relevant warnings (W_EMPTY_BETWEEN) collected as nodes */
  readonly betweens: Expr[] = [];
  readonly tickUnits: Span[] = [];

  constructor(
    readonly text: string,
    readonly part: 'setup' | 'outcome',
    toks: Tok[],
    readonly env: ParamEnv,
  ) {
    this.toks = toks;
  }

  // ---- token helpers -------------------------------------------------------
  private peek(k = 0): Tok {
    return this.toks[Math.min(this.i + k, this.toks.length - 1)];
  }
  private next(): Tok {
    const t = this.toks[this.i];
    if (this.i < this.toks.length - 1) this.i++;
    return t;
  }
  private kw(t: Tok, ...words: string[]): boolean {
    return t.type === 'IDENT' && words.includes(t.v);
  }
  private punct(t: Tok, p: string): boolean {
    return t.type === 'PUNCT' && t.v === p;
  }
  private col(offset: number): number {
    return lineCol(this.text, offset).column;
  }
  private span(from: Tok, to: Tok): Span {
    return { offset: from.offset, length: to.offset + to.length - from.offset };
  }
  private prevTok(): Tok {
    return this.toks[Math.max(0, this.i - 1)];
  }
  private fail(code: string, at: Span, message: string): never {
    throw new SyntaxFail({ code, offset: at.offset, length: Math.max(1, at.length), message });
  }
  private check(code: string, at: Span, message: string): void {
    this.checks.push({ code, offset: at.offset, length: Math.max(1, at.length), message });
  }
  /** An error when `exp` was needed at the current token. */
  private expected(exp: string): never {
    const t = this.peek();
    if (t.type === 'EOF') this.fail('E_UNEXPECTED_TOKEN', t, `The ${this.part} ends too early: expected ${exp}.`);
    this.fail('E_EXPECTED', t, `Expected ${exp} at column ${this.col(t.offset)}, found '${t.text}'.`);
  }
  private unexpected(exp: string): never {
    const t = this.peek();
    if (t.type === 'EOF') this.fail('E_UNEXPECTED_TOKEN', t, `The ${this.part} ends too early: expected ${exp}.`);
    this.fail('E_UNEXPECTED_TOKEN', t, `Unexpected '${t.text}' at column ${this.col(t.offset)}.`);
  }
  private expectEnd(): void {
    if (this.peek().type !== 'EOF') this.unexpected('the end');
  }

  // ---- texts -----------------------------------------------------------------
  parseSetup(): Expr {
    const t = this.peek();
    if (this.kw(t, 'all')) {
      this.next();
      this.expectEnd();
      return { t: 'all', span: { offset: t.offset, length: t.length } };
    }
    const e = this.parseExpr();
    this.expectEnd();
    return e;
  }

  parseOutcome(): Outcome {
    const t0 = this.peek();
    const isEvent = this.kw(t0, 'touches', 'trades', 'closes') || (this.kw(t0, 'not') && this.kw(this.peek(1), 'touches', 'trades', 'closes'));
    const whole: Span = { offset: t0.offset, length: Math.max(1, this.text.trimEnd().length - t0.offset) };
    if (!isEvent) {
      const e = this.parseExpr();
      this.expectEnd();
      return { form: 'state', expr: e, span: whole };
    }
    let neg = false;
    let notTok: Tok | null = null;
    if (this.kw(t0, 'not')) {
      notTok = this.next();
      neg = true;
    }
    const first = this.parseEvent();
    let seq: 'before' | 'then' | null = null;
    let second: EventSpec | null = null;
    if (this.kw(this.peek(), 'before', 'then')) {
      if (notTok) this.fail('E_NOT_SEQUENCE', notTok, `'not' applies to one event. Write the opposite sequence instead, or test each event alone.`);
      seq = this.next().v as 'before' | 'then';
      second = this.parseEvent();
    }
    let from: Clause | null = null;
    let end: Clause | null = null;
    for (;;) {
      const t = this.peek();
      if (!this.kw(t, 'from', 'by', 'within')) break;
      const c = this.parseClause();
      if (c.kind === 'from') {
        if (from) this.fail('E_DUPLICATE_CLAUSE', c.span, 'The outcome already has a from clause.');
        from = c;
      } else {
        if (end) {
          if (end.kind !== c.kind) this.fail('E_DUPLICATE_CLAUSE', c.span, 'Use either by or within, not both.');
          this.fail('E_DUPLICATE_CLAUSE', c.span, `The outcome already has a ${c.kind} clause.`);
        }
        end = c;
      }
    }
    this.expectEnd();
    return { form: 'event', neg, first, seq, second, from, end, span: whole } satisfies EventOutcome;
  }

  private parseEvent(): EventSpec {
    const t = this.peek();
    let kind: EventKindName;
    if (this.kw(t, 'touches')) {
      this.next();
      kind = 'touches';
    } else if (this.kw(t, 'trades', 'closes')) {
      this.next();
      const d = this.peek();
      if (!this.kw(d, 'above', 'below')) this.expected("'above' or 'below'");
      this.next();
      kind = `${t.v}_${d.v}` as EventKindName;
    } else this.expected('an event (touches, trades or closes)');
    const lv = this.peek();
    const level = this.parseSum();
    const levelEnd = this.prevTok();
    let barSize = 1;
    if ((kind === 'closes_above' || kind === 'closes_below') && this.kw(this.peek(), 'on')) {
      this.next();
      const d = this.parseDuration();
      barSize = d.minutes;
      if (!BAR_SIZES.includes(d.minutes))
        this.check('E_BAR_SIZE', d.span, `Bars of ${fmtNum(d.minutes)} minutes are not offered. Use 1, 2, 3, 5, 10, 15, 20, 30 or 60.`);
    }
    return { kind, level, barSize, levelSpan: this.span(lv, levelEnd), span: this.span(t, this.prevTok()) };
  }

  private parseClause(): Clause {
    const k = this.next();
    if (k.v === 'from') {
      const t = this.peek();
      if (t.type !== 'TIME') this.expected('a time');
      this.next();
      const sm = sessionMinute(t.num);
      if (sm >= 1380) this.check('E_TIME_IN_HALT', t, `${t.v} falls in the daily 17:00 to 18:00 halt, when no session trades.`);
      return { kind: 'from', time: sm, span: this.span(k, t) };
    }
    if (k.v === 'by') {
      const t = this.peek();
      if (t.type === 'TIME') {
        this.next();
        const sm = sessionMinute(t.num);
        if (sm > 1380) this.check('E_TIME_IN_HALT', t, `${t.v} falls in the daily 17:00 to 18:00 halt, when no session trades.`);
        return { kind: 'by', time: sm, span: this.span(k, t) };
      }
      if (this.kw(t, 'close', 'session_close')) {
        this.next();
        return { kind: 'by', end: t.v as 'close' | 'session_close', span: this.span(k, t) };
      }
      this.expected('a time, close or session_close');
    }
    const d = this.parseDuration();
    const span = { offset: k.offset, length: d.span.offset + d.span.length - k.offset };
    if (!Number.isInteger(d.minutes) || d.minutes < 1 || d.minutes > 1380)
      this.check('E_ARG_RANGE', span, `The minutes of within must be a whole number from 1 to 1380; got ${fmtNum(d.minutes)}.`);
    return { kind: 'within', minutes: d.minutes, span };
  }

  private parseDuration(): { minutes: number; span: Span } {
    const t = this.peek();
    if (t.type === 'NUMBER' || t.type === 'PARAM') {
      const u = this.peek(1);
      if (u.type === 'IDENT' && (MINUTE_UNITS.has(u.v) || HOUR_UNITS.has(u.v))) {
        this.next();
        this.next();
        const v = t.type === 'NUMBER' ? t.num : this.paramValue(t, 'duration-unit');
        return { minutes: HOUR_UNITS.has(u.v) ? v * 60 : v, span: this.span(t, u) };
      }
      if (t.type === 'PARAM') {
        this.next();
        const v = this.paramValue(t, 'duration');
        return { minutes: v, span: { offset: t.offset, length: t.length } };
      }
      this.fail('E_BAD_DURATION', t, `'${t.text}' is not a duration. Write minutes (30m) or hours (1h).`);
    }
    if (t.type === 'EOF') this.fail('E_UNEXPECTED_TOKEN', t, `The ${this.part} ends too early: expected a duration.`);
    this.fail('E_BAD_DURATION', t, `'${t.text}' is not a duration. Write minutes (30m) or hours (1h).`);
  }

  /** The value of a PARAM token in a given position, recording check errors. */
  private paramValue(t: Tok, where: 'value' | 'duration' | 'duration-unit' | 'number'): number {
    const name = t.v;
    this.env.used.add(name);
    const decl = this.env.decls.get(name);
    const has = this.env.values.has(name);
    if (!has) {
      this.check('E_UNKNOWN_PARAM', t, `The parameter ${t.text} has no value. Give it one with param: or the params option.`);
      return NaN;
    }
    const unit: ParamUnit = decl ? decl.unit : 'none';
    if (where === 'duration') {
      const lenient = !decl || (decl.source !== 'preset' && decl.unit === 'none');
      if (unit !== 'minutes' && !lenient) this.check('E_BAD_DURATION', t, `'${t.text}' is not a duration. Write minutes (30m) or hours (1h).`);
    } else if (unit === 'minutes') {
      this.check('E_TYPE', t, `The parameter ${t.text} is a number of minutes; use it where a duration belongs, such as within ${t.text}.`);
    }
    return this.env.values.get(name)!;
  }

  // ---- expressions --------------------------------------------------------------
  parseExpr(): Expr {
    return this.parseOr();
  }

  private parseOr(): Expr {
    let l = this.parseAnd();
    while (this.kw(this.peek(), 'or')) {
      const op = this.next();
      const r = this.parseAnd();
      l = { t: 'or', l, r, span: op };
    }
    return l;
  }

  private parseAnd(): Expr {
    let l = this.parseNot();
    while (this.kw(this.peek(), 'and')) {
      const op = this.next();
      const r = this.parseNot();
      l = { t: 'and', l, r, span: op };
    }
    return l;
  }

  private parseNot(): Expr {
    const t = this.peek();
    if (this.kw(t, 'not')) {
      this.next();
      const x = this.parseNot();
      return { t: 'not', x, span: t };
    }
    return this.parseRelation();
  }

  private isCmp(t: Tok): boolean {
    return t.type === 'OP' && ['>', '>=', '<', '<=', '=', '!='].includes(t.v);
  }

  private parseRelation(): Expr {
    const l = this.parseSum();
    const t = this.peek();
    let e: Expr = l;
    if (this.isCmp(t)) {
      this.next();
      const r = this.parseSum();
      e = { t: 'cmp', op: t.v as CmpOp, l, r, span: t };
    } else if (this.kw(t, 'between')) {
      this.next();
      const a = this.parseSum();
      if (!this.kw(this.peek(), 'and')) this.expected("'and'");
      this.next();
      const b = this.parseSum();
      e = { t: 'between', x: l, a, b, span: t };
      this.betweens.push(e);
    } else if (this.kw(t, 'in') || (this.kw(t, 'not') && this.kw(this.peek(1), 'in'))) {
      const neg = this.kw(t, 'not');
      this.next();
      if (neg) this.next();
      if (!this.punct(this.peek(), '(')) this.expected("'('");
      this.next();
      const list: Expr[] = [this.parseSum()];
      while (this.punct(this.peek(), ',')) {
        this.next();
        list.push(this.parseSum());
      }
      if (!this.punct(this.peek(), ')')) this.expected("',' or ')'");
      this.next();
      e = { t: 'in', x: l, list, neg, span: t };
    } else return l;
    const n = this.peek();
    if (this.isCmp(n) || this.kw(n, 'between', 'in') || (this.kw(n, 'not') && this.kw(this.peek(1), 'in')))
      this.fail('E_CHAINED_COMPARISON', n, 'Comparisons cannot be chained. For a range write: x between a and b.');
    return e;
  }

  parseSum(): Expr {
    let l = this.parseProduct();
    for (;;) {
      const t = this.peek();
      if (t.type === 'OP' && (t.v === '+' || t.v === '-')) {
        this.next();
        const r = this.parseProduct();
        l = { t: 'bin', op: t.v as ArithOp, l, r, span: t };
      } else return l;
    }
  }

  private parseProduct(): Expr {
    let l = this.parseUnary();
    for (;;) {
      const t = this.peek();
      if (t.type === 'OP' && (t.v === '*' || t.v === '/')) {
        this.next();
        const r = this.parseUnary();
        l = { t: 'bin', op: t.v as ArithOp, l, r, span: t };
      } else return l;
    }
  }

  private parseUnary(): Expr {
    const t = this.peek();
    if (t.type === 'OP' && t.v === '-') {
      this.next();
      const x = this.parseUnary();
      return { t: 'neg', x, span: t };
    }
    return this.parsePostfix();
  }

  private parsePostfix(): Expr {
    const startTok = this.peek();
    const p = this.parsePrimary();
    if (p.kind === 'expr') {
      if (this.punct(this.peek(), '.')) this.unexpected('the end');
      return p.e;
    }
    let win = p.win;
    for (;;) {
      if (!this.punct(this.peek(), '.')) {
        const owner = renderWinBase(win);
        this.fail('E_EXPECTED', p.span, `Expected a field after '${owner}', such as ${owner}.high.`);
      }
      this.next();
      const f = this.peek();
      if (f.type !== 'IDENT') this.expected('a field');
      this.next();
      if (win.k === 'prior' && !win.session && f.v === 'session') {
        win = { ...win, session: true };
        continue;
      }
      if ((FIELDS as readonly string[]).includes(f.v)) {
        const e: Expr = { t: 'win', win, field: f.v as Field, span: this.span(startTok, f) };
        if (this.punct(this.peek(), '.')) this.unexpected('the end');
        return e;
      }
      const owner = renderWinBase(win);
      const cands: string[] = [...FIELDS];
      if (win.k === 'prior' && !win.session) cands.push('session');
      this.fail(
        'E_UNKNOWN_FIELD',
        f,
        `'${f.text}' is not a field of ${owner}. Fields are open, high, low, close, range, mid, body and volume.${suggest(f.v, cands)}`,
      );
    }
  }

  private parsePrimary(): Primary {
    const t = this.peek();
    if (t.type === 'NUMBER' || t.type === 'PARAM') return { kind: 'expr', e: this.parseQuantity() };
    if (this.punct(t, '(')) {
      this.next();
      const e = this.parseExpr();
      if (!this.punct(this.peek(), ')')) this.expected("')'");
      this.next();
      return { kind: 'expr', e };
    }
    if (t.type === 'IDENT') {
      if (isKeyword(t.v) && t.v !== 'close') this.unexpected('a value');
      if (this.punct(this.peek(1), '(')) return this.parseCall();
      return this.parseName();
    }
    this.expected('a value');
  }

  private parseQuantity(): Expr {
    const t = this.next();
    let value: number;
    let unit: Unit = 'none';
    let param: string | null = null;
    let declUnit: ParamUnit = 'none';
    if (t.type === 'NUMBER') value = t.num;
    else {
      param = t.v;
      const decl = this.env.decls.get(t.v);
      declUnit = decl ? decl.unit : 'none';
      value = this.paramValue(t, 'value');
      if (declUnit === '%') unit = '%';
      else if (declUnit === 'points') unit = 'pts';
    }
    let unitSpan: Span | null = null;
    let of: Expr | null = null;
    const u = this.peek();
    let written: Unit = 'none';
    if (u.type === 'PERCENT') {
      this.next();
      written = '%';
      unitSpan = u;
      if (this.kw(this.peek(), 'of')) {
        this.next();
        of = this.parsePostfix();
      }
    } else if (u.type === 'IDENT' && PRICE_UNITS.has(u.v)) {
      this.next();
      written = u.v.startsWith('tick') ? 'ticks' : 'pts';
      unitSpan = u;
    }
    if (written !== 'none') {
      if (param !== null && declUnit !== 'none')
        this.check('E_TYPE', u, `The parameter ${t.text} already has the unit ${declUnit}; write it without a unit.`);
      unit = written;
    }
    if (unit === 'ticks' && unitSpan) this.tickUnits.push(unitSpan);
    return { t: 'num', value, unit, of, span: this.span(t, this.prevTok()), unitSpan, param };
  }

  private parseName(): Primary {
    const t = this.next();
    const v = t.v;
    const sp: Span = { offset: t.offset, length: t.length };
    switch (v) {
      case 'rth':
      case 'overnight':
      case 'session':
        return { kind: 'base', win: { k: v }, span: sp };
      case 'prior':
        return { kind: 'base', win: { k: 'prior', n: 1, session: false, written: false }, span: sp };
      case 'gap':
        return { kind: 'expr', e: { t: 'gap', span: sp } };
      case 'weekday':
        return { kind: 'expr', e: { t: 'weekday', span: sp } };
      case 'early_close':
        return { kind: 'expr', e: { t: 'early_close', span: sp } };
    }
    if ((EVENT_KINDS as readonly string[]).includes(v))
      return { kind: 'expr', e: { t: 'event', kinds: [v as EventKind], before: 0, after: 0, call: false, named: [], span: sp } };
    if (v in WEEKDAYS) return { kind: 'expr', e: { t: 'wdname', day: WEEKDAYS[v], span: sp } };
    if (BAD_WEEKDAYS.has(v)) this.fail('E_BAD_WEEKDAY', t, `'${t.text}' is not a trading weekday. Use mon, tue, wed, thu or fri.`);
    const om = /^or([0-9]+)$/.exec(v);
    if (om) {
      const n = Number(om[1]);
      if (n < 1 || n > 390) this.check('E_ARG_RANGE', t, `The N of orN must be a whole number from 1 to 390; got ${n}.`);
      return { kind: 'base', win: { k: 'or', n }, span: sp };
    }
    if (FUNCTIONS.includes(v)) this.expected("'('");
    this.fail('E_UNKNOWN_NAME', t, `'${t.text}' is not a value Setup Odds knows.${nameSuggestion(v)}`);
  }

  private parseArgs(fn: string): { args: Arg[]; close: Tok } {
    this.next(); // '('
    const args: Arg[] = [];
    const eventish = fn === 'event' || fn === 'days_since' || fn === 'days_to';
    if (this.punct(this.peek(), ')')) return { args, close: this.next() };
    for (;;) {
      let name: string | null = null;
      const t0 = this.peek();
      if (t0.type === 'IDENT' && this.peek(1).type === 'OP' && this.peek(1).v === '=') {
        name = t0.v;
        this.next();
        this.next();
      }
      const t = this.peek();
      const after = this.peek(1);
      const endsArg = (x: Tok): boolean => this.punct(x, ',') || this.punct(x, ')');
      if (eventish && name === null && t.type === 'IDENT' && endsArg(after)) {
        this.next();
        args.push({ kind: 'ident', tok: t, name, span: t });
      } else if (t.type === 'TIME') {
        this.next();
        args.push({ kind: 'time', tok: t, name, span: t });
      } else if ((t.type === 'NUMBER' || t.type === 'PARAM') && after.type === 'IDENT' && (MINUTE_UNITS.has(after.v) || HOUR_UNITS.has(after.v))) {
        const d = this.parseDuration();
        args.push({ kind: 'duration', minutes: d.minutes, name, span: d.span });
      } else if (t.type === 'PARAM' && endsArg(after) && this.env.decls.get(t.v)?.unit === 'minutes') {
        const d = this.parseDuration();
        args.push({ kind: 'duration', minutes: d.minutes, name, span: d.span });
      } else {
        const first = this.peek();
        const e = this.parseSum();
        args.push({ kind: 'sum', e, name, span: this.span(first, this.prevTok()) });
      }
      const n = this.peek();
      if (this.punct(n, ',')) {
        this.next();
        continue;
      }
      if (this.punct(n, ')')) return { args, close: this.next() };
      this.expected("',' or ')'");
    }
  }

  private argText(a: Arg): string {
    return this.text.slice(a.span.offset, a.span.offset + a.span.length);
  }

  private wholeArg(fn: string, a: Arg, what: string, min: number, max: number): number {
    if (a.kind !== 'sum' || a.e.t !== 'num' || a.e.unit !== 'none' || a.e.of) {
      this.check('E_ARG_KIND', a.span, `${fn} needs a whole number here, not '${this.argText(a)}'.`);
      return min;
    }
    const v = a.e.value;
    if (Number.isNaN(v)) return min;
    if (!Number.isInteger(v) || v < min || v > max) {
      this.check('E_ARG_RANGE', a.span, `${what} must be a whole number from ${min} to ${max}; got ${fmtNum(v)}.`);
      return Number.isInteger(v) && v >= min ? max : min;
    }
    return v;
  }

  private count(fn: string, args: Arg[], at: Span, min: number, max: number): boolean {
    if (args.length < min || args.length > max) {
      const exp = min === max ? String(min) : `${min} or more`;
      this.check('E_ARG_COUNT', at, `${fn} takes ${exp} argument(s); ${args.length} given.`);
      return false;
    }
    return true;
  }

  private timeArg(fn: string, a: Arg | undefined): number | null {
    if (!a) return null;
    if (a.kind !== 'time') {
      this.check('E_ARG_KIND', a.span, `${fn} needs a time here, not '${this.argText(a)}'.`);
      return null;
    }
    return sessionMinute(a.tok.num);
  }

  private noNamed(fn: string, args: Arg[]): void {
    for (const a of args) if (a.name !== null) this.check('E_ARG_KIND', a.span, `${fn} needs a value here, not '${a.name}='.`);
  }

  private parseCall(): Primary {
    const nameTok = this.next();
    const fn = nameTok.v;
    if (!FUNCTIONS.includes(fn)) {
      this.fail('E_UNKNOWN_NAME', nameTok, `'${nameTok.text}' is not a value Setup Odds knows.${nameSuggestion(fn)}`);
    }
    const { args, close } = this.parseArgs(fn);
    const whole = this.span(nameTok, close);
    const at: Span = { offset: nameTok.offset, length: nameTok.length };
    const halt = (t: Tok): void => this.check('E_TIME_IN_HALT', t, `${t.v} falls in the daily 17:00 to 18:00 halt, when no session trades.`);
    if (fn !== 'event') this.noNamed(fn, args);
    switch (fn) {
      case 'prior': {
        let n = 1;
        if (this.count(fn, args, at, 1, 1)) n = this.wholeArg(fn, args[0], 'The k of prior(k)', 1, 20);
        return { kind: 'base', win: { k: 'prior', n, session: false, written: true }, span: whole };
      }
      case 'adr':
      case 'atr': {
        let n = 1;
        if (this.count(fn, args, at, 1, 1)) n = this.wholeArg(fn, args[0], `The n of ${fn}(n)`, 1, 100);
        return { kind: 'expr', e: { t: fn, n, span: whole } };
      }
      case 'window': {
        let a = 930, b = 960;
        if (this.count(fn, args, at, 2, 2)) {
          const ta = this.timeArg(fn, args[0]);
          const tb = this.timeArg(fn, args[1]);
          let ok = ta !== null && tb !== null;
          if (ta !== null && ta >= 1380) {
            halt((args[0] as { tok: Tok }).tok);
            ok = false;
          }
          if (tb !== null && tb > 1380) {
            halt((args[1] as { tok: Tok }).tok);
            ok = false;
          }
          if (ok) {
            a = ta!;
            b = tb!;
            if (a >= b) {
              this.check('E_WINDOW_ORDER', whole, `The window must start before it ends; ${clockOfSessionMinute(a)} to ${clockOfSessionMinute(b)} is empty.`);
              b = a + 1;
            }
          }
        }
        return { kind: 'base', win: { k: 'window', a, b }, span: whole };
      }
      case 'bar': {
        let t = 930, len = 1;
        if (this.count(fn, args, at, 2, 2)) {
          const tt = this.timeArg(fn, args[0]);
          if (tt !== null && tt >= 1380) halt((args[0] as { tok: Tok }).tok);
          else if (tt !== null) t = tt;
          const la = args[1];
          if (la.kind !== 'duration') this.check('E_ARG_KIND', la.span, `bar needs a duration here, not '${this.argText(la)}'.`);
          else {
            const max = 1380 - t;
            if (!Number.isInteger(la.minutes) || la.minutes < 1 || la.minutes > max)
              this.check('E_ARG_RANGE', la.span, `The length of bar(T, L) must be a whole number from 1 to ${max}; got ${fmtNum(la.minutes)}.`);
            else len = la.minutes;
          }
        }
        return { kind: 'base', win: { k: 'bar', t, len }, span: whole };
      }
      case 'at': {
        let time = 960;
        if (this.count(fn, args, at, 1, 1)) {
          const tt = this.timeArg(fn, args[0]);
          if (tt !== null) {
            if (tt > 1380) halt((args[0] as { tok: Tok }).tok);
            else if (tt === 0)
              this.check('E_EMPTY_WINDOW', args[0].span, 'The outcome window is empty: it starts at 18:00 and ends at 18:00.');
            else time = tt;
          }
        }
        return { kind: 'expr', e: { t: 'at', time, span: whole } };
      }
      case 'event': {
        const kinds: EventKind[] = [];
        let before = 0, after = 0;
        const named: ('before' | 'after')[] = [];
        let sawNamed = false;
        for (const a of args) {
          if (a.name === null) {
            if (sawNamed) {
              this.check('E_ARG_KIND', a.span, `event needs before= or after= here, not '${this.argText(a)}'.`);
              continue;
            }
            const k = this.kindArg(fn, a);
            if (k) kinds.push(k);
          } else {
            sawNamed = true;
            if (a.name !== 'before' && a.name !== 'after') {
              this.check('E_ARG_KIND', a.span, `event needs before= or after= here, not '${a.name}='.`);
              continue;
            }
            const v = this.wholeArg(fn, a, a.name, 0, 5);
            if (a.name === 'before') before = v;
            else after = v;
            if (!named.includes(a.name)) named.push(a.name);
          }
        }
        if (args.filter((a) => a.name === null).length === 0) this.count(fn, [], at, 1, Infinity);
        return { kind: 'expr', e: { t: 'event', kinds: kinds.length ? kinds : ['fomc'], before, after, call: true, named, span: whole } };
      }
      case 'days_since':
      case 'days_to': {
        let kind: EventKind = 'fomc';
        if (this.count(fn, args, at, 1, 1)) kind = this.kindArg(fn, args[0]) ?? 'fomc';
        return { kind: 'expr', e: { t: fn, kind, span: whole } };
      }
      default: {
        // abs, min, max, mid
        const f = fn as 'abs' | 'min' | 'max' | 'mid';
        const [mn, mx] = f === 'abs' ? [1, 1] : f === 'mid' ? [2, 2] : [2, Infinity];
        const exprs: Expr[] = [];
        this.count(fn, args, at, mn, mx);
        for (const a of args) {
          if (a.kind === 'sum') exprs.push(a.e);
          else this.check('E_ARG_KIND', a.span, `${fn} needs a value here, not '${this.argText(a)}'.`);
        }
        return { kind: 'expr', e: { t: 'fn', fn: f, args: exprs, span: at } };
      }
    }
  }

  private kindArg(fn: string, a: Arg): EventKind | null {
    if (a.kind === 'ident' && (EVENT_KINDS as readonly string[]).includes(a.tok.v)) return a.tok.v as EventKind;
    this.check('E_ARG_KIND', a.span, `${fn} needs an event kind (fomc, cpi, nfp, opex or roll) here, not '${this.argText(a)}'.`);
    return null;
  }
}

export function fmtNum(v: number): string {
  return String(v);
}

export interface TextParse<T> {
  ok: boolean;
  node: T | null;
  syntax: RawError | null;
  parser: Parser | null;
  toks: Tok[];
}

/** Lex and parse one text. */
export function parseText(text: string, part: 'setup' | 'outcome', env: ParamEnv, maxChars: number): TextParse<Expr | Outcome> {
  if (text.length > maxChars)
    return { ok: false, node: null, syntax: { code: 'E_TOO_LONG', offset: 0, length: text.length, message: `The ${part} is ${text.length} characters long; the limit is ${maxChars}.` }, parser: null, toks: [] };
  if (text.trim() === '')
    return { ok: false, node: null, syntax: { code: 'E_EMPTY', offset: text.length, length: 1, message: `The ${part} is empty.` }, parser: null, toks: [] };
  const lx = lex(text);
  if (lx.error) {
    const e = lx.error;
    const column = lineCol(text, e.offset).column;
    const message =
      e.code === 'E_BAD_TIME'
        ? `'${e.tok}' is not a clock time. Write HH:MM on a 24-hour clock, New York time.`
        : `'${e.tok}' is not part of the language (column ${column}).`;
    return { ok: false, node: null, syntax: { code: e.code, offset: e.offset, length: e.length, message }, parser: null, toks: lx.toks };
  }
  const p = new Parser(text, part, lx.toks, env);
  try {
    const node = part === 'setup' ? p.parseSetup() : p.parseOutcome();
    return { ok: true, node, syntax: null, parser: p, toks: lx.toks };
  } catch (err) {
    if (err instanceof SyntaxFail) return { ok: false, node: null, syntax: err.err, parser: p, toks: lx.toks };
    throw err;
  }
}
